  return {
    packs,
    packEntries,
    rules,
    accept,
    sharedConstants: Array.isArray(raw.sharedConstants) ? raw.sharedConstants : [],
    packConfig,
    taskScheduler,
    claudinite: raw.claudinite ?? null,
    maintenance: raw.maintenance ?? null,
    // Passed through as declared. Neither is normalized here — `claudinite` is the
    // vendored-mount provenance stamp the `stamp` signal reads, and `maintenance`
    // is the delivery preference baselining's worker reads off the raw file. They
    // are in CONFIG_KEYS, so declaring them is legal and raises no error; omitting
    // them from THIS shape is what made the stamp invisible to the scheduler and
    // silently killed baselining fleet-wide (every repo self-skipped as "no
    // vendored mount"). A key that validates but does not survive the load is the
    // worst kind: legal to write, impossible to read, and silent in both
    // directions. `configKeysSurviveLoad` in the tests pins the whole set.
    errors,
  };
}

